#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# ── Helpers for this wizard (organisation-level writes, records, checks) ──

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TICKET_ISSUE=1   # "Wiring step 1" in the studio repo's GitHub Issues
TEST_REPO="studio-collab-check"
STUDIO_REPO="studio"
API="https://api.github.com"

# load KEY...: set $KEY from ENV_FILE if a value was saved on an earlier run.
load() { local k v; for k in "$@"; do v=$(_existing "$k" || true); printf -v "$k" '%s' "$v"; done; }

# skip_if_done ID: on a re-run, offer to skip a stage already finished.
skip_if_done() {
  [[ "$(_existing "DONE_$1" || true)" == yes ]] || return 1
  note "This stage was finished on an earlier run."
  confirm "Skip it?"
}
mark_done() { write_env "DONE_$1" yes >/dev/null; }

gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# set_org_secret NAME VALUE: organisation secret, visible to all repositories.
set_org_secret() {
  local name="$1" value="$2"
  if gh_ready && printf '%s' "$value" | gh secret set "$name" --org "$ORG" --visibility all >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name (org)")
    printf '  %s✓ set%s organisation secret %s\n' "$GREEN" "$RESET" "$name"
    return
  fi
  SKIPPED+=("org secret $name (gh secret set $name --org $ORG --visibility all)")
  warn "couldn't set organisation secret $name; set it later"
}

# set_org_var NAME VALUE: organisation variable, visible to all repositories.
set_org_var() {
  local name="$1" value="$2"
  if gh_ready && gh variable set "$name" --org "$ORG" --visibility all --body "$value" >/dev/null 2>&1; then
    printf '  %s✓ set%s organisation variable %s = %s\n' "$GREEN" "$RESET" "$name" "$value"
    return
  fi
  SKIPPED+=("org variable $name=$value (gh variable set $name --org $ORG --visibility all --body ...)")
  warn "couldn't set organisation variable $name; set it later"
}

# record "text": a dated comment on the ticket's GitHub issue, for the results
# the ticket asks to be recorded.
record() {
  local body; body=$(printf '**%s, wiring-step-1 wizard:** %s' "$(date +%F)" "$1")
  if gh issue comment "$TICKET_ISSUE" -R "$ORG/$STUDIO_REPO" --body "$body" >/dev/null 2>&1; then
    printf '  %s✓ recorded%s on issue #%s\n' "$GREEN" "$RESET" "$TICKET_ISSUE"
  else
    SKIPPED+=("comment on $ORG/$STUDIO_REPO#$TICKET_ISSUE: $1")
    warn "couldn't comment on issue #$TICKET_ISSUE; it's listed at the end"
  fi
}

# ask_yes KEY "question": a y/N answer saved as yes/no in $KEY.
ask_yes() { if confirm "$2"; then printf -v "$1" yes; else printf -v "$1" no; fi; }

# ── Acting as the studio app (JWT → installation token), with openssl ─────

_b64url() { openssl base64 -A | tr '+/' '-_' | tr -d '='; }

app_jwt() {
  local now header payload unsigned sig
  now=$(date +%s)
  header=$(printf '{"alg":"RS256","typ":"JWT"}' | _b64url)
  payload=$(printf '{"iat":%s,"exp":%s,"iss":"%s"}' $((now - 60)) $((now + 540)) "$STUDIO_APP_CLIENT_ID" | _b64url)
  unsigned="$header.$payload"
  sig=$(printf '%s' "$unsigned" | openssl dgst -sha256 -sign "$STUDIO_APP_PEM" | _b64url)
  printf '%s.%s' "$unsigned" "$sig"
}

# api AUTH METHOD PATH [JSON]: sets API_CODE and API_BODY; never fails.
api() {
  local auth="$1" method="$2" path="$3" data="${4:-}" out
  out=$(mktemp)
  API_CODE=$(curl -sS -o "$out" -w '%{http_code}' -X "$method" \
    -H "Authorization: Bearer $auth" -H "Accept: application/vnd.github+json" \
    ${data:+-d "$data"} "$API$path" 2>/dev/null) || API_CODE=000
  API_BODY=$(cat "$out"); rm -f "$out"
}

# app_token: mint an installation token for $ORG into APP_TOKEN; also sets
# STUDIO_APP_SLUG. Returns 1 with a warning on failure.
app_token() {
  local jwt inst
  jwt=$(app_jwt) || { warn "couldn't sign a JWT with $STUDIO_APP_PEM"; return 1; }
  api "$jwt" GET /app
  [[ "$API_CODE" == 200 ]] || { warn "GET /app failed (HTTP $API_CODE): check the Client ID and key"; return 1; }
  STUDIO_APP_SLUG=$(jq -r .slug <<<"$API_BODY")
  api "$jwt" GET "/orgs/$ORG/installation"
  [[ "$API_CODE" == 200 ]] || { warn "the app isn't installed on $ORG (HTTP $API_CODE)"; return 1; }
  inst=$(jq -r .id <<<"$API_BODY")
  api "$jwt" POST "/app/installations/$inst/access_tokens"
  [[ "$API_CODE" == 201 ]] || { warn "couldn't mint an installation token (HTTP $API_CODE)"; return 1; }
  APP_TOKEN=$(jq -r .token <<<"$API_BODY")
}

# ask_pem: make sure STUDIO_APP_PEM points at a readable private key.
ask_pem() {
  while :; do
    if [[ -n "${STUDIO_APP_PEM:-}" && -f "$STUDIO_APP_PEM" ]] && openssl pkey -in "$STUDIO_APP_PEM" -noout >/dev/null 2>&1; then
      return 0
    fi
    [[ -n "${STUDIO_APP_PEM:-}" ]] && warn "not a readable private key: $STUDIO_APP_PEM"
    ask STUDIO_APP_PEM "Path to the downloaded .pem file (drag it into this window):"
    STUDIO_APP_PEM="${STUDIO_APP_PEM%"${STUDIO_APP_PEM##*[![:space:]]}"}"   # trim trailing space from drag-and-drop
    STUDIO_APP_PEM="${STUDIO_APP_PEM/#\~/$HOME}"
  done
}

# alchemy ARGS...: run the Alchemy v2 CLI from a throwaway pnpm project, with
# any Cloudflare credentials in the environment removed so the profile wins.
ALCHEMY_DIR=""
alchemy() {
  if [[ -z "$ALCHEMY_DIR" ]]; then
    ALCHEMY_DIR=$(mktemp -d)
    say "Installing alchemy@latest into a throwaway folder…"
    (cd "$ALCHEMY_DIR" && pnpm init >/dev/null && pnpm add alchemy@latest >/dev/null) \
      || { warn "pnpm add alchemy@latest failed"; return 1; }
  fi
  (cd "$ALCHEMY_DIR" && env -u CLOUDFLARE_API_TOKEN -u CLOUDFLARE_ACCOUNT_ID -u CLOUDFLARE_API_KEY \
      -u CLOUDFLARE_EMAIL -u CLOUDFLARE_ACCOUNT_EMAIL -u CI pnpm exec alchemy "$@")
}

# alchemy_account PROFILE ACCOUNT_ID LABEL: one Alchemy profile, checked, then
# its state store bootstrapped.
alchemy_account() {
  local profile="$1" account="$2" label="$3"
  say "Profile ${BOLD}$profile${RESET} → the $label account ($account)."
  alchemy profile create "$profile" 2>/dev/null || note "(profile $profile already exists, which is fine)"
  step "Next, Alchemy asks how to sign in to Cloudflare: choose OAuth (browser)."
  step "If it asks which account, pick the $label account, ID $account."
  pause "Press Enter to start the sign-in…"
  alchemy profile edit --profile "$profile" --add Cloudflare || alchemy profile edit --profile "$profile" --reconfigure Cloudflare
  printf '\n'
  alchemy profile show --profile "$profile" || true
  printf '\n'
  until confirm "Does the accountId above match $account (it may be shortened)?"; do
    warn "Wrong account: reconfigure and pick the $label account."
    alchemy profile edit --profile "$profile" --reconfigure Cloudflare
    alchemy profile show --profile "$profile" || true
  done
  say "Bootstrapping the state store in the $label account…"
  if alchemy state bootstrap --backend cloudflare --profile "$profile"; then
    printf '  %s✓ state store ready%s in the %s account\n' "$GREEN" "$RESET" "$label"
  else
    warn "state bootstrap failed; fix the error above and re-run this stage"
    return 1
  fi
}

# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=13
# --from N starts at stage N, using the values saved by earlier runs.
FROM=1
if [[ "${1:-}" == --from ]]; then FROM="${2:-}"; elif [[ "${1:-}" == --from=* ]]; then FROM="${1#--from=}"; fi
if ! [[ "$FROM" =~ ^[0-9]+$ ]] || (( FROM < 1 || FROM > TOTAL_STAGES )); then
  warn "--from takes a stage number, 1 to $TOTAL_STAGES"; exit 1
fi
at() { (( $1 >= FROM )); }

# The library defaults ENV_FILE to ./.env, which would sit in the repo about to
# be published, so this wizard keeps its own file outside it.
ENV_FILE="${STUDIO_WIZARD_ENV:-${XDG_CONFIG_HOME:-$HOME/.config}/studio/wiring-step-1.env}"
mkdir -p "$(dirname "$ENV_FILE")" && chmod 700 "$(dirname "$ENV_FILE")"
cd "$REPO_ROOT"

load ORG STUDIO_APP_CLIENT_ID STUDIO_APP_PEM STUDIO_APP_SLUG COLLAB_ONLY_OK \
     CLAUDE_CODE_OAUTH_TOKEN_EXPIRES CLOUDFLARE_PREVIEW_ACCOUNT_ID CLOUDFLARE_PRODUCTION_ACCOUNT_ID
if (( FROM > 1 )); then
  [[ -n "$ORG" ]] || { warn "No saved organisation in $ENV_FILE: start from stage 1 or 2."; exit 1; }
  gh_ready || { warn "gh isn't logged in: run 'gh auth login -h github.com -s admin:org,delete_repo,workflow'."; exit 1; }
  HUMAN_LOGIN=$(gh api user --jq .login)
fi

title="Wiring step 1: organisation, studio app, accounts and secrets"
(( FROM > 1 )) && title+=" · resuming at stage $FROM"
banner "$title"
_STAGE_INDEX=$((FROM - 1))

# ── 1 ────────────────────────────────────────────────────────────────────
if at 1; then
stage "Before we start"
for tool in gh openssl jq curl git pnpm node claude; do
  command -v "$tool" >/dev/null 2>&1 || { warn "missing: $tool. Install it, then re-run."; exit 1; }
done
node_major=$(node -p 'process.versions.node.split(".").map(Number).reduce((a,n,i)=>a+n*[1e6,1e3,1][i],0)')
(( node_major >= 24011001 )) || { warn "Alchemy needs Node 24.11.1 or later (you have $(node --version))."; exit 1; }
say "Values are saved for re-runs in $ENV_FILE (no secrets: those go straight to GitHub)."
if [[ -n "${CLAUDE_CODE_RETRY_WATCHDOG:-}" ]]; then
  warn "CLAUDE_CODE_RETRY_WATCHDOG is set in your shell ($CLAUDE_CODE_RETRY_WATCHDOG)."
  say "The spec keeps it off. Remove it from your shell profile and open a new terminal."
  pause "Press Enter once it's removed (or Ctrl-C to stop)…"
else
  printf '  %s✓%s CLAUDE_CODE_RETRY_WATCHDOG is not set (retry watchdog off)\n' "$GREEN" "$RESET"
fi
say "gh needs the admin:org, delete_repo and workflow scopes on top of repo."
if gh_ready; then
  gh auth refresh -h github.com -s admin:org,delete_repo,workflow
else
  step "gh's saved login is invalid. Log in: choose GitHub.com, HTTPS, and log in with a browser."
  gh auth login -h github.com -s admin:org,delete_repo,workflow
fi
gh_ready || { warn "gh still isn't logged in."; exit 1; }
HUMAN_LOGIN=$(gh api user --jq .login)
printf '  %s✓%s gh is logged in as %s\n' "$GREEN" "$RESET" "$HUMAN_LOGIN"
pause
fi

# ── 2 ────────────────────────────────────────────────────────────────────
if at 2; then
stage "GitHub organisation"
if ! skip_if_done org; then
  say "Create a free organisation that will own every studio repo."
  open_url "https://github.com/account/organizations/new?plan=free"
  step "Choose the Free plan if asked."
  step "Pick an organisation name, and choose 'My personal account' as the owner."
  step "Skip inviting members: you are the only member."
  pause "Press Enter once the organisation exists…"
fi
while :; do
  ask ORG "Organisation name (as in github.com/<name>):"
  if gh api "orgs/$ORG" >/dev/null 2>&1; then break; fi
  warn "gh can't see organisation '$ORG'. Check the name, and that gh is granted access to it."
done
write_env ORG "$ORG"
members=$(gh api "orgs/$ORG/members" --jq 'length' 2>/dev/null || echo "?")
if [[ "$members" == 1 ]]; then
  printf '  %s✓%s %s has exactly one member\n' "$GREEN" "$RESET" "$ORG"
else
  warn "$ORG has $members members; the spec wants you as the only one."
fi
mark_done org
pause
fi

# ── 3 ────────────────────────────────────────────────────────────────────
if at 3; then
stage "Studio app: register"
if ! skip_if_done app; then
  say "Register the studio app: a private GitHub App owned by $ORG. The form opens prefilled."
  perms="actions=write&checks=write&contents=write&issues=write&pull_requests=write&workflows=write"
  perms+="&vulnerability_alerts=read&metadata=read&organization_actions_variables=read"
  open_url "https://github.com/organizations/$ORG/settings/apps/new?name=$ORG-studio&url=https://github.com/$ORG&public=false&webhook_active=false&$perms"
  step "GitHub App name: $ORG-studio (any unused name works). Homepage URL: https://github.com/$ORG"
  step "Webhook: untick 'Active'."
  step "Check every permission (prefilling may miss some). Repository: Actions, Checks,"
  step "  Contents, Issues, Pull requests and Workflows: Read & write; Dependabot alerts"
  step "  and Metadata: Read-only. Organization: Variables: Read-only. All else: No access."
  step "Where can this GitHub App be installed? → 'Only on this account'. Create GitHub App."
  step "On the app's settings page, copy the Client ID (not the App ID)."
  ask STUDIO_APP_CLIENT_ID "Client ID:"
  write_env STUDIO_APP_CLIENT_ID "$STUDIO_APP_CLIENT_ID"
  step "Left sidebar → Credentials → Key pairs → New key. A .pem file downloads."
  ask_pem
  write_env STUDIO_APP_PEM "$STUDIO_APP_PEM"
  set_org_secret STUDIO_APP_PRIVATE_KEY "$(cat "$STUDIO_APP_PEM")"
  set_org_var STUDIO_APP_CLIENT_ID "$STUDIO_APP_CLIENT_ID"
  note "Keep the .pem file for now: stage 5 uses it, then offers to delete it."
  mark_done app
fi
pause
fi

# ── 4 ────────────────────────────────────────────────────────────────────
if at 4; then
stage "Studio app: install on all repositories"
if ! skip_if_done install; then
  open_url "https://github.com/organizations/$ORG/settings/apps"
  step "Click Edit next to the studio app → Install App (left sidebar)."
  step "Click Install next to $ORG → choose 'All repositories' → Install."
  pause "Press Enter once it's installed…"
  mark_done install
fi
pause
fi

# ── 5 ────────────────────────────────────────────────────────────────────
if at 5; then
stage "Check: the studio app under 'Collaborators only'"
if ! skip_if_done collab; then
  say "On a new empty repo with 'Collaborators only' on, can the studio app open an issue"
  say "and a PR? And does the 'All repositories' installation see a repo made after it?"
  ask_pem
  if gh repo view "$ORG/$TEST_REPO" >/dev/null 2>&1; then
    note "$ORG/$TEST_REPO already exists from an earlier run; reusing it."
  else
    gh repo create "$ORG/$TEST_REPO" --public --add-readme \
      --description "Throwaway: studio app vs Collaborators only. Deleted straight after." >/dev/null
    printf '  %s✓ created%s %s/%s\n' "$GREEN" "$RESET" "$ORG" "$TEST_REPO"
  fi
  gh api -X PATCH "repos/$ORG/$TEST_REPO" -f pull_request_creation_policy=collaborators_only >/dev/null 2>&1 || true
  pr_policy=$(gh api "repos/$ORG/$TEST_REPO" --jq '.pull_request_creation_policy // "unknown"' 2>/dev/null || echo unknown)
  open_url "https://github.com/$ORG/$TEST_REPO/settings"
  step "Under Features → Issues: keep Issues ticked and set the dropdown to 'Collaborators only'."
  if [[ "$pr_policy" == collaborators_only ]]; then
    printf '  %s✓%s pull requests already set to Collaborators only (via the API)\n' "$GREEN" "$RESET"
  else
    step "Under Features → Pull requests: set the dropdown to 'Collaborators only'."
  fi
  pause "Press Enter once both say 'Collaborators only'…"

  sees=no; issue=fail; pr=fail
  if app_token; then
    write_env STUDIO_APP_SLUG "$STUDIO_APP_SLUG"
    api "$APP_TOKEN" GET "/installation/repositories?per_page=100"
    jq -e --arg n "$TEST_REPO" '.repositories | any(.name == $n)' <<<"$API_BODY" >/dev/null 2>&1 && sees=yes
    api "$APP_TOKEN" POST "/repos/$ORG/$TEST_REPO/issues" '{"title":"Studio app check","body":"Opened by the studio app."}'
    issue="HTTP $API_CODE"; [[ "$API_CODE" == 201 ]] && issue=ok
    api "$APP_TOKEN" GET "/repos/$ORG/$TEST_REPO/git/ref/heads/main"
    sha=$(jq -r '.object.sha // empty' <<<"$API_BODY" 2>/dev/null || true)
    api "$APP_TOKEN" POST "/repos/$ORG/$TEST_REPO/git/refs" "{\"ref\":\"refs/heads/app-check\",\"sha\":\"$sha\"}"
    api "$APP_TOKEN" PUT "/repos/$ORG/$TEST_REPO/contents/app-check.txt" \
      "{\"message\":\"Studio app check\",\"branch\":\"app-check\",\"content\":\"$(printf 'check\n' | openssl base64 -A)\"}"
    if [[ "$API_CODE" == 201 || "$API_CODE" == 200 ]]; then
      api "$APP_TOKEN" POST "/repos/$ORG/$TEST_REPO/pulls" '{"title":"Studio app check","head":"app-check","base":"main"}'
      pr="HTTP $API_CODE"; [[ "$API_CODE" == 201 ]] && pr=ok
    else
      pr="couldn't push a branch (HTTP $API_CODE)"
    fi
  fi
  printf '\n'
  say "Installation sees the new repo: ${BOLD}$sees${RESET}"
  say "App opened an issue:            ${BOLD}$issue${RESET}"
  say "App opened a PR:                ${BOLD}$pr${RESET}"
  printf '\n'
  if [[ "$issue" == ok && "$pr" == ok ]]; then
    COLLAB_ONLY_OK=yes
    record "Collaborators-only check passed: on an empty public repo with 'Collaborators only' on for issues and PRs, the studio app ($STUDIO_APP_SLUG) opened an issue and a PR. The restriction stays on."
  else
    COLLAB_ONLY_OK=no
    warn "The studio app was blocked. Fallback: 'Collaborators only' stays off for issues and"
    warn "PRs, the actor check stands alone, and outsiders' issues and PRs are closed by hand."
    record "Collaborators-only check FAILED (issue: $issue; PR: $pr). Fallback applied: 'Collaborators only' is off for issues and PRs, the actor check stands alone, and outsiders' issues and PRs are closed by hand."
  fi
  write_env COLLAB_ONLY_OK "$COLLAB_ONLY_OK"
  if [[ "$sees" == yes ]]; then
    record "New-repo check passed: the 'All repositories' installation saw $TEST_REPO, created after it was installed. No extra step in the setup script (ticket 03)."
  else
    warn "The installation didn't see the new repo: adding each new repo becomes a setup-script step."
    record "New-repo check FAILED: the 'All repositories' installation did not see $TEST_REPO, created after it was installed. Adding each new repo to the installation becomes a step of the setup script (for ticket 03)."
  fi
  printf '\n'
  if confirm "Delete $ORG/$TEST_REPO now (it can't be undone)?"; then
    gh repo delete "$ORG/$TEST_REPO" --yes && printf '  %s✓ deleted%s %s/%s\n' "$GREEN" "$RESET" "$ORG" "$TEST_REPO"
  else
    SKIPPED+=("delete the test repo: gh repo delete $ORG/$TEST_REPO --yes")
  fi
  if confirm "Delete the .pem file now? (Its key is in the STUDIO_APP_PRIVATE_KEY secret.)"; then
    rm -f "$STUDIO_APP_PEM" && printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$STUDIO_APP_PEM"
  else
    SKIPPED+=("delete the private key file $STUDIO_APP_PEM")
  fi
  mark_done collab
fi
pause
fi

# ── 6 ────────────────────────────────────────────────────────────────────
if at 6; then
stage "Check: workflow execution protection"
if ! skip_if_done protection; then
  say "Can a free organisation save a policy that lets only you and the studio app"
  say "start workflows? If it saves, it stays on (Active) from today."
  open_url "https://github.com/organizations/$ORG/settings/actions"
  step "In the left sidebar, under Actions, open Policies → create a new policy."
  step "Name: 'Only the human and the studio app'. Target: all repositories."
  step "Add 'Restrict actors': allow the user $HUMAN_LOGIN and the GitHub App ${STUDIO_APP_SLUG:-(the studio app)}."
  step "Enforcement: Active. Save."
  ask_yes PROTECTION_SAVED "Did the policy save, Active?"
  if [[ "$PROTECTION_SAVED" == yes ]]; then
    record "Workflow execution protection check passed: an Active org policy restricting actors to $HUMAN_LOGIN and the studio app saved on the free organisation. It is on from wiring step 1, so when a run is unexpectedly blocked in later steps, check this policy first."
  else
    ask PROTECTION_ERROR "What did GitHub say (short)?"
    record "Workflow execution protection check FAILED: the policy could not be saved on a free organisation ($PROTECTION_ERROR). The actor check stands alone."
  fi
  mark_done protection
fi
pause
fi

# ── 7 ────────────────────────────────────────────────────────────────────
if at 7; then
stage "Dependabot: alerts on, security updates off"
if ! skip_if_done dependabot; then
  open_url "https://github.com/organizations/$ORG/settings"
  step "Left sidebar → Security → Advanced Security → Configurations → New configuration"
  step "  → Custom configuration. Name it 'Studio'."
  step "Dependency graph: Enabled. Dependabot alerts: Enabled. Security updates: Disabled."
  step "Leave every other feature at its default; anything paid doesn't apply to public repos."
  step "Policy: 'Use as default for newly created repositories' → All repositories."
  step "Enforce configuration: Enforce. Save."
  ask_yes DEPENDABOT_OK "Did it save?"
  if [[ "$DEPENDABOT_OK" != yes ]]; then
    ask DEPENDABOT_ERROR "What blocked it (short)?"
    record "Dependabot org-wide configuration could not be saved ($DEPENDABOT_ERROR). Turn Dependabot alerts on and security updates off per repo instead."
    SKIPPED+=("Dependabot: alerts on, security updates off (see the ticket comment)")
  fi
  mark_done dependabot
fi
pause
fi

# ── 8 ────────────────────────────────────────────────────────────────────
if at 8; then
stage "Claude: one-year token, expiry date, usage credits off"
if ! skip_if_done claude; then
  if confirm "Run 'claude setup-token' for a new token? (Answer N to paste one you already have.)"; then
    say "Approve access in the browser, then copy the token it prints."
    claude setup-token || warn "claude setup-token exited with an error"
    printf '\n'
  fi
  note "A long token can wrap onto several lines when copied; that's fine, paste it all."
  while :; do
    ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token (hidden), then press Enter:"
    # A wrapped paste arrives as several lines: gather the rest of it, so none
    # spills into the next prompt, and drop every line break and space.
    while IFS= read -rs -t 1 more; do CLAUDE_CODE_OAUTH_TOKEN+="$more"; done
    CLAUDE_CODE_OAUTH_TOKEN="${CLAUDE_CODE_OAUTH_TOKEN//[[:space:]]/}"
    say "Got ${#CLAUDE_CODE_OAUTH_TOKEN} characters, starting ${CLAUDE_CODE_OAUTH_TOKEN:0:13}… and ending …${CLAUDE_CODE_OAUTH_TOKEN: -4}."
    [[ "$CLAUDE_CODE_OAUTH_TOKEN" == sk-ant-* ]] || warn "that doesn't start like a Claude token (sk-ant-)"
    confirm "Does the ending match the token you copied?" && break
    CLAUDE_CODE_OAUTH_TOKEN=""
  done
  _clear; [[ -t 1 ]] && printf '\033[3J'   # also wipe scrollback, which holds the token
  set_org_secret CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
  unset CLAUDE_CODE_OAUTH_TOKEN
  default_expiry=$(date -v+1y +%F 2>/dev/null || date -d '+1 year' +%F)
  while :; do
    ask CLAUDE_CODE_OAUTH_TOKEN_EXPIRES "Expiry date, YYYY-MM-DD [Enter for $default_expiry]:"
    CLAUDE_CODE_OAUTH_TOKEN_EXPIRES="${CLAUDE_CODE_OAUTH_TOKEN_EXPIRES:-$default_expiry}"
    [[ "$CLAUDE_CODE_OAUTH_TOKEN_EXPIRES" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] && break
    warn "use the form YYYY-MM-DD"
  done
  write_env CLAUDE_CODE_OAUTH_TOKEN_EXPIRES "$CLAUDE_CODE_OAUTH_TOKEN_EXPIRES"
  set_org_var CLAUDE_CODE_OAUTH_TOKEN_EXPIRES "$CLAUDE_CODE_OAUTH_TOKEN_EXPIRES"
  printf '\n'
  open_url "https://claude.ai/settings/usage"
  step "Find the 'Usage credits' section: its toggle must be off. Switch it off if it's on."
  until confirm "Is Usage credits off?"; do warn "Runs would bill at API rates while it's on."; done
  mark_done claude
fi
pause
fi

# ── 9 ────────────────────────────────────────────────────────────────────
if at 9; then
stage "Cloudflare: preview and production accounts"
if ! skip_if_done cf_accounts; then
  say "Two accounts under your one login, kept apart from any personal account:"
  say "  ${BOLD}Studio preview${RESET} on Workers Free, ${BOLD}Studio production${RESET} on Workers Paid (\$5/month)."
  note "Needs a login at least 7 days old and Super Administrator on an existing account."
  open_url "https://dash.cloudflare.com/"
  step "Go to Accounts (account list / switcher) → Create Account → name 'Studio preview' → Create Account."
  step "Do it again for 'Studio production'."
  pause "Press Enter once both exist…"
  step "Switch to Studio production, then open the Workers plans page:"
  open_url "https://dash.cloudflare.com/?to=/:account/workers/plans"
  step "If asked to pick an account, pick Studio production. Choose Workers Paid and check out."
  until confirm "Is Studio production on Workers Paid (and Studio preview still on Free)?"; do :; done
  mark_done cf_accounts
fi
say "Account IDs: in each account, press Cmd/Ctrl+K, type 'Copy account ID', press Enter."
for key in CLOUDFLARE_PREVIEW_ACCOUNT_ID CLOUDFLARE_PRODUCTION_ACCOUNT_ID; do
  label=preview; [[ "$key" == *PRODUCTION* ]] && label=production
  while :; do
    ask "$key" "Studio $label account ID:"
    [[ "${!key}" =~ ^[0-9a-f]{32}$ ]] && break
    warn "an account ID is 32 lowercase hex characters"
  done
  write_env "$key" "${!key}"
done
[[ "$CLOUDFLARE_PREVIEW_ACCOUNT_ID" != "$CLOUDFLARE_PRODUCTION_ACCOUNT_ID" ]] || { warn "both IDs are the same; re-run this stage"; exit 1; }
set_org_var CLOUDFLARE_PREVIEW_ACCOUNT_ID "$CLOUDFLARE_PREVIEW_ACCOUNT_ID"
pause
fi

# ── 10 ───────────────────────────────────────────────────────────────────
if at 10; then
stage "Alchemy: preview profile and state store"
if ! skip_if_done alchemy_preview; then
  alchemy_account preview "$CLOUDFLARE_PREVIEW_ACCOUNT_ID" preview || exit 1
  mark_done alchemy_preview
fi
pause
fi

# ── 11 ───────────────────────────────────────────────────────────────────
if at 11; then
stage "Alchemy: production profile and state store"
if ! skip_if_done alchemy_production; then
  alchemy_account production "$CLOUDFLARE_PRODUCTION_ACCOUNT_ID" production || exit 1
  mark_done alchemy_production
fi
[[ -n "$ALCHEMY_DIR" ]] && rm -rf "$ALCHEMY_DIR"
pause
fi

# ── 12 ───────────────────────────────────────────────────────────────────
if at 12; then
stage "Cloudflare: the preview account's token"
if ! skip_if_done cf_token; then
  say "An account-owned token in Studio preview, for preview deploys from CI."
  open_url "https://dash.cloudflare.com/$CLOUDFLARE_PREVIEW_ACCOUNT_ID"
  step "Check you're in Studio preview → Manage account → Account API tokens → Create Token."
  step "Custom token, name 'studio-preview-ci', no expiry. Account permissions, all Edit/Write:"
  step "  Secrets Store, Workers Scripts, Workers KV Storage, Workers R2 Storage, D1,"
  step "  Queues, Pages, Account Settings; plus Workers Tail: Read."
  note "Alchemy's suggested CI list. Trimming it to the minimum is ticket 03's job."
  step "Continue to summary → Create Token → copy it (it starts cfat_)."
  ask_secret CLOUDFLARE_PREVIEW_API_TOKEN "Paste the token (hidden):"
  verify=$(curl -sS -H "Authorization: Bearer $CLOUDFLARE_PREVIEW_API_TOKEN" \
    "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_PREVIEW_ACCOUNT_ID/tokens/verify" 2>/dev/null \
    | jq -r '.result.status // "unknown"' 2>/dev/null || echo unknown)
  if [[ "$verify" == active ]]; then
    printf '  %s✓%s Cloudflare says the token is active\n' "$GREEN" "$RESET"
  else
    warn "couldn't confirm the token is active (got: $verify); check it in the dashboard"
  fi
  set_org_secret CLOUDFLARE_PREVIEW_API_TOKEN "$CLOUDFLARE_PREVIEW_API_TOKEN"
  unset CLOUDFLARE_PREVIEW_API_TOKEN
  mark_done cf_token
fi
pause
fi

# ── 13 ───────────────────────────────────────────────────────────────────
if at 13; then
stage "Publish the studio repo"
if ! skip_if_done publish; then
  if ! git rev-parse --verify -q HEAD >/dev/null; then
    say "The first commit takes everything except .scratch/ (its tickets move to GitHub Issues next):"
    git status --short -- . ':(exclude).scratch' | sed 's/^/    /'
    if confirm "Make the first commit, 'Initial commit', with these files?"; then
      git add -A -- . ':(exclude).scratch'
      git commit -q -m "Initial commit"
      printf '  %s✓ committed%s %s\n' "$GREEN" "$RESET" "$(git log --oneline -1)"
    else
      warn "No commit, so nothing to publish. Re-run this stage when ready."; exit 1
    fi
  fi
  if ! gh repo view "$ORG/$STUDIO_REPO" >/dev/null 2>&1; then
    confirm "Publish it as the PUBLIC repo $ORG/$STUDIO_REPO?" || { warn "Not published."; exit 1; }
    gh repo create "$ORG/$STUDIO_REPO" --public --source . --remote origin --push \
      --description "The software studio: shared workflows, task definitions, standards and the project template."
  fi
  if [[ "$COLLAB_ONLY_OK" == yes ]]; then
    gh api -X PATCH "repos/$ORG/$STUDIO_REPO" -f pull_request_creation_policy=collaborators_only >/dev/null 2>&1 || true
    open_url "https://github.com/$ORG/$STUDIO_REPO/settings"
    step "Features → Issues: 'Collaborators only'. Pull requests: check it says 'Collaborators only' too."
    pause "Press Enter once both are set…"
  else
    note "'Collaborators only' stays off (the stage 5 check failed): the actor check stands alone."
  fi
  if gh api "repos/$ORG/$STUDIO_REPO/rulesets" --jq '.[].name' 2>/dev/null | grep -qx main-requires-pr; then
    note "The main-requires-pr ruleset already exists."
  else
    gh api -X POST "repos/$ORG/$STUDIO_REPO/rulesets" --input - >/dev/null <<'JSON'
{"name":"main-requires-pr","target":"branch","enforcement":"active",
 "conditions":{"ref_name":{"include":["~DEFAULT_BRANCH"],"exclude":[]}},
 "bypass_actors":[{"actor_type":"OrganizationAdmin","actor_id":null,"bypass_mode":"pull_request"}],
 "rules":[{"type":"deletion"},{"type":"non_fast_forward"},
  {"type":"pull_request","parameters":{"required_approving_review_count":0,"dismiss_stale_reviews_on_push":false,
   "require_code_owner_review":false,"require_last_push_approval":false,"required_review_thread_resolution":false}}]}
JSON
    printf '  %s✓%s main now takes changes only by PR (ruleset main-requires-pr)\n' "$GREEN" "$RESET"
  fi
  if gh api "repos/$ORG/$STUDIO_REPO/vulnerability-alerts" >/dev/null 2>&1; then
    printf '  %s✓%s Dependabot alerts are on for %s (the default configuration applied)\n' "$GREEN" "$RESET" "$STUDIO_REPO"
  else
    warn "Dependabot alerts aren't on for $STUDIO_REPO: apply the Studio configuration to it."
  fi
  record "Studio repo published as public $ORG/$STUDIO_REPO; main protected by the ruleset main-requires-pr (PRs only, org admins may bypass through a PR). Org names are in docs/org-secrets-and-variables.md; the token-expiry variable is CLAUDE_CODE_OAUTH_TOKEN_EXPIRES (YYYY-MM-DD)."
  mark_done publish
fi
say "Next: ask Claude to move the tickets into GitHub Issues and rewrite the tracker docs."
pause
fi

finish
}

run_wizard "$@"; exit
